// Renders the release banners for a major release into docs/public/images, in
// the dark look of the docs site: four formats (banner, og, square and
// portrait), each at 1x and 2x, as palette PNGs. The swatches on each banner
// are generated by Möbius itself, from the build in dist.
//
// Usage: npm run build, then npm run banners -- <release>, e.g. 2.0
// The content is in scripts/banners/<release>.mjs. Rendering uses a local
// Chrome (CHROME=/path/to/chrome to choose one), Python with Pillow and the
// docs site's system fonts, so nothing is fetched from the network.
import { execFileSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const OUT = join(ROOT, 'docs', 'public', 'images');
const CHROME = process.env.CHROME ?? 'google-chrome';
const FORMATS = [
  { suffix: '', width: 1200, height: 600, layout: 'wide' },
  { suffix: '-og', width: 1200, height: 630, layout: 'wide' },
  { suffix: '-square', width: 1080, height: 1080, layout: 'tall' },
  { suffix: '-portrait', width: 1080, height: 1350, layout: 'tall' }
];
const SCALES = [1, 2];
// The font stacks of docs/.vitepress/theme/ph/variables.css
const SANS =
  'ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, Noto Sans, sans-serif';
const MONO =
  'Menlo, DejaVu Sans Mono, Consolas, Monaco, Ubuntu Mono, monospace';
const release = process.argv[2];
const build = join(ROOT, 'dist', 'moebius.js');

if (!release) {
  console.error('Usage: npm run banners -- <release>, e.g. 2.0');
  process.exit(1);
}

if (!existsSync(build)) {
  console.error('dist/moebius.js is missing: run npm run build first');
  process.exit(1);
}

const { default: content } = await import(
  pathToFileURL(join(ROOT, 'scripts', 'banners', `${release}.mjs`)).href
);
const { default: Moebius } = await import(pathToFileURL(build).href);
// The banners show no names; one is passed so Moebius() fetches no list
const { MoebiusColor, MoebiusPalettes } = await Moebius({
  colorNames: { Base: content.baseColor }
});
const { colors } = new MoebiusPalettes({
  baseColor: new MoebiusColor(content.baseColor),
  secondaryColor: new MoebiusColor(content.secondaryColor),
  numberOfColors: 8
});
const escape = (text) =>
  String(text)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
const mark = readFileSync(join(ROOT, 'docs', 'public', 'logo', 'logo.svg'), {
  encoding: 'utf8'
}).replace('<svg ', '<svg class="mark" ');
const title = content.title
  .map((part) =>
    typeof part === 'string'
      ? escape(part)
      : `<span class="accent">${escape(part.accent)}</span>`
  )
  .join('<br>');
const swatches = (name) =>
  colors[name].map((hex) => `<i style="background: ${hex}"></i>`).join('');
const rows = content.palettes
  .map(
    (name) =>
      `<div class="row"><span>${escape(name)}</span><div class="strip">${swatches(name)}</div></div>`
  )
  .join('');
const page = (layout, format) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><style>
:root { --bg: #181a22; --bg-2: #262a3b; --well: #1f222a; --line: #2d313b;
  --text: #9fa8ad; --accent-text: #e4e4e7; --brand: #6ca7f9; }
* { box-sizing: border-box; margin: 0; }
html, body { width: 100%; height: 100%; }
body { position: relative; overflow: hidden; color: var(--text); font-family: ${SANS};
  background: radial-gradient(circle at 78% 50%, var(--bg-2) 0, var(--bg) 70%) var(--bg); }
.pill, h1, p, .panel { position: absolute; }
.pill { display: inline-flex; align-items: center; gap: 14px; padding: 10px 22px 10px 12px;
  border: 1px solid var(--line); border-radius: 999px; background: var(--bg);
  font: 18px ${MONO}; color: var(--text); }
.mark { width: 30px; height: 30px; }
h1 { color: var(--accent-text); font-weight: 700; line-height: 1.06; letter-spacing: -0.03em; }
.accent { color: var(--brand); }
p { line-height: 1.5; }
/* A well, like the docs site's code blocks, that the swatches sit in */
.panel { display: flex; flex-direction: column; justify-content: space-between;
  padding: 26px 28px; border: 1px solid var(--line); border-radius: 12px; background: var(--well); }
.panel header { display: flex; align-items: center; gap: 10px; font: 16px ${MONO};
  color: var(--text); }
.panel header i { width: 18px; height: 18px; border-radius: 50%; }
.panel header b { margin-left: auto; font-weight: 400; color: var(--brand); }
.row span { display: block; margin-bottom: 10px; font: 16px ${MONO}; color: var(--text); }
.strip { display: flex; height: 44px; border-radius: 8px; overflow: hidden; }
.strip i { flex: 1; }
/* wide: text left, the palettes right */
.wide .pill { top: 64px; left: 72px; }
.wide h1 { top: 172px; left: 72px; width: 580px; font-size: 56px; }
.wide p { bottom: 64px; left: 72px; width: 520px; font-size: 20px; }
.wide .panel { top: 64px; right: 72px; bottom: 64px; width: 460px; }
/* tall: text on top, the palettes below */
.tall .pill { top: 80px; left: 80px; font-size: 22px; }
.tall .mark { width: 36px; height: 36px; }
.tall h1 { top: 192px; left: 80px; width: 920px; font-size: 88px; }
.tall p { top: 420px; left: 80px; width: 900px; font-size: 28px; }
.tall .panel { left: 80px; right: 80px; bottom: 72px; height: 420px; padding: 28px 36px; }
.tall .panel header, .tall .row span { font-size: 20px; }
.tall .strip { height: 36px; }
.portrait .tall .panel { height: 620px; bottom: 120px; }
.portrait .tall .strip { height: 80px; }
</style></head>
<body class="${format}"><main class="${layout}">
  <div class="pill">${mark}${escape(content.pill)}</div>
  <h1>${title}</h1>
  <p>${escape(content.body)}</p>
  <div class="panel">
    <header><i style="background: ${content.baseColor}"></i>${escape(content.baseColor)}
      <i style="background: ${content.secondaryColor}"></i>${escape(content.secondaryColor)}
      <b>MoebiusPalettes</b></header>
    ${rows}
  </div>
</main></body></html>`;
const work = mkdtempSync(join(tmpdir(), 'moebius-banners-'));
const outputs = [];

mkdirSync(OUT, { recursive: true });

try {
  for (const { suffix, width, height, layout } of FORMATS) {
    const file = join(work, `${suffix || 'banner'}.html`);

    writeFileSync(file, page(layout, suffix.slice(1)));

    for (const scale of SCALES) {
      const path = join(
        OUT,
        `moebius-${content.slug}${suffix}${scale === 2 ? '@2x' : ''}.png`
      );

      execFileSync(
        CHROME,
        [
          '--headless=new',
          '--disable-gpu',
          '--hide-scrollbars',
          `--user-data-dir=${join(work, 'profile')}`,
          `--force-device-scale-factor=${scale}`,
          `--window-size=${width},${height}`,
          `--screenshot=${path}`,
          pathToFileURL(file).href
        ],
        { stdio: 'ignore' }
      );
      outputs.push(path);
    }
  }
} finally {
  rmSync(work, { recursive: true, force: true });
}

// A palette of up to 256 colours keeps flat artwork sharp and small
execFileSync(
  'python3',
  [
    '-c',
    `import sys
from PIL import Image
for path in sys.argv[1:]:
    image = Image.open(path)
    image = image.convert('RGBA') if image.mode != 'RGBA' else image
    image.quantize(256, method=Image.Quantize.FASTOCTREE).save(path, optimize=True)`,
    ...outputs
  ],
  { stdio: 'inherit' }
);

for (const path of outputs) {
  console.log(`${relative(ROOT, path)}: ${statSync(path).size} bytes`);
}
